import pandas as pd

def find_candidates(candidates: pd.DataFrame) -> pd.DataFrame:
    skills = {'Python', 'Tableau', 'PostgreSQL'}
    filtered = candidates[candidates['skill'].isin(skills)]
    grouped = filtered.groupby('candidate_id')['skill'].nunique().reset_index()
    matched = grouped[grouped['skill'] == 3][['candidate_id']]
    return matched.sort_values(by='candidate_id')
